msg = msg + (argstr && msg ? " " | "") + argstr;
ok = 1;
for o in (setremove(this.location.contents, this))
  if (is_player(o) && index(msg, o.name) == 1)
    ok = 0;
  endif
endfor
if (!(ok && (index(msg, player:name()) || index(msg, player.name))))
