    else
      s = "nothing";
    endif
  else
    s = $object_utils:has_property(what, prop) ? what.(prop) | $it.(prop);
  endif
  if (ucase && s && typeof(s) == STR && (z = strcmp(s[1], "`")) < 27 && z > 0)
    s = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"[z] + s[2..length(s)];
