"a \"c_\" in the verb name means that the first (and only the first) name in the list will be capitalized.";
v = verb[1..rindex(verb, "_") - 1];
first = args[1] ? {args[1][1]:(v)()} | {};
if (v[c = (i = index(v, "_")) ? i - 1 | length(v)] == "c")
  v[c..c] = "";
