"$string_utils:binary_string_to_lines(STR data[, STR encoding]) -> {LIST of STR}";
"Take a binary string (see `help encode_binary') and an optional encoding (default: UTF-8)";
"and return a list of strings, one per line of the input. Unedecodable bytes are skipped.";
{data, ?encoding = "UTF-8"} = args;
chunks = decode_chars(data, "UTF-8");
lines = {};
line = "";
idx = 1;
end = length(chunks);
while (idx <= end)
  chunk = chunks[idx];
  if (typeof(chunk) == STR)
    if (line)
      line = line + chunk;
    else
      line = chunk;
    endif
    idx = idx + 1;
  elseif (chunk == 13 && idx + 1 <= end && chunks[idx + 1] == 10)
    lines = {@lines, line};
    line = "";
    idx = idx + 2;
  elseif (chunk == 10)
    lines = {@lines, line};
    line = "";
    idx = idx + 1;
  else
    "skip binary data";
    idx = idx + 1;
  endif
endwhile
if (line)
  lines = {@lines, line};
endif
return lines;
