s = 1;
while (s <= l)
  n = n + seq[s];
  if (s >= l || n <= seq[s + 1])
    return {@seq[1..s], n};
  endif
  n = n - seq[s + 1];
  s = s + 2;
endwhile
return seq;

":lastn(seq,n) => last n elements of seq as a sequence.";
