    endif
  endfor
  return {bogus, @sofar};
else
  fwd = include_recip = 0;
  if (recip == $nothing || recip in seen)
    return sofar;
  elseif (!valid(recip) || (!(is_player(recip) || $object_utils:isa(recip, $mail_recipient)) || typeof(fwd = recip:mail_forward(from)) != LIST))
