    endif
    sofar = result[2..3];
  else
    include_recip = 1;
  endif
  if (ticks_left() < 1000 || seconds_left() < 2)
    suspend(0);
  endif
  biffs = sofar[2];
  for n in (this:mail_notify(recip, from))
    if (valid(n))
      if (i = $list_utils:iassoc_suspended(n, biffs))
        biffs[i] = setadd(biffs[i], recip);
