msgs = seq = {};
for s in (caller.messages_going)
  msgs = {@msgs, @s[2]};
endfor
if (verb == "expunge_rmm")
  caller.messages_going = {};
else
  for x in (msgs)
    player:tell($string_utils:right(x[1], 4), ":  ", caller:msg_summary_line(@x[2]));
    if (ticks_left() < 500 || seconds_left() < 2)
