  "...show year...";
  c = ctime(args[1]);
  date = c[5..11] + c[21..25];
else
  date = ctime(args[1])[5..16];
endif
from = args[2];
while (subs = match(from, " ([^)]*)"))
  from[subs[1]..subs[2]] = "";
endwhile
if (args[4] != " ")
  subject = args[4];
endif
return tostr(date, "   ", $string_utils:left(from, 15), "   ", subject);

":msg_summary_line(@msg) => date/from/subject as a single string.";
