if (blank < length(args) && args[blank + 1])
  if (length(args[blank + 1]) <= 28)
    subject = args[blank + 1];
  else
    subject = args[blank + 1][1..25] + "...";
  endif
else
  subject = "(None.)";
endif
if (typeof(args[1]) == NUM)
  date = ctime(args[1])[5..16];
  start = 2;
else
