  if (typeof(i) == LIST)
    verb_mod = ou:match_verb(o, "modname_" + i[1]);
    verb_builder = ou:match_verb(o, "namebuilder_" + i[1]);
    if (!verb_builder || (verb_mod && verb_builder[1] in ou:ancestors(verb_mod[1])))
      ret = {@ret, {dummy, @i}};
    else
      ret = {@ret, {`this:("namebuilder_" + i[1])() ! ANY => dummy', @i}};
    endif
  elseif (typeof(i) == STR)
    for j in [1..length(i)]
      verb_mod = ou:match_verb(o, "modname_" + i[j]);
      verb_builder = ou:match_verb(o, "namebuilder_" + i[j]);
      if (!verb_builder || (verb_mod && verb_builder[1] in ou:ancestors(verb_mod[1])))
        ret = {@ret, {dummy, i[j]}};
