":_find_distance_bfs(origin, {dests}[, all_obvious[, walker]]) => {distances}";
"";
"For all dests, find the shortest walking distance for each and return them.  If all_obvious, pass through unobvious exits.  If walker is supplied, use walker for obviousness checks instead of player.";
"";
{origin, destinations, ?all_obvious = 0, ?walker = player} = args;
if (typeof(destinations) != LIST)
  destinations = {destinations};
endif
distances = $list_utils:make(length(destinations), $maxint);
if (i = origin in destinations)
  distances[i] = 0;
  if (length(distances) == 1)
    "well, that was easy.  let's not search the whole moo";
    return distances;
  endif
  found = 1;
else
  found = 0;
endif
rooms = {origin};
dists = {1};
which = 1;
while (which <= length(rooms))
  check = rooms[which];
  dist = dists[which];
  which = which + 1;
  for exit in (`check.exits ! ANY => {}')
    "for exit in (check:objects_for_match())";
    "if (!$object_utils:isa(exit, $exit))";
    " continue exit;";
    "endif";
    if (all_obvious || `exit:obvious(walker) ! ANY')
      dest = `exit.dest ! ANY => #-1';
      if ((i = dest in destinations) && distances[i] > dist)
        distances[i] = dist;
        found = found + 1;
        if (found == length(distances))
          return distances;
        endif
      endif
      if (!(dest in rooms))
        rooms = {@rooms, dest};
        dists = {@dists, dist + 1};
      endif
    endif
  endfor
endwhile
return distances;
