":_find_direction_bfs(origin, {dests}[, all_obvious]) => {{ew, ns, ud}, ...}";
"";
"For all dests, find the shortest walking path to each and return vectors indicating how many east/west, north/south and up/down exits were traversed to get there.";
"";
{origin, destinations, ?all_obvious = 0} = args;
if (typeof(destinations) != LIST)
  destinations = {destinations};
endif
"the fourth element is a tag";
unreachable = {0, 0, 0, #-1};
distances = $list_utils:make(length(destinations), unreachable);
if ({origin} == destinations)
  "well, that was easy.  let's not search the whole moo";
  return distances;
endif
found = 0;
rooms = {origin};
dists = {{0, 0, 0}};
"got these ideas from Amit's automap (#2442) :force";
su = $set_utils;
which = 1;
south_names = {"s", "south", "sw", "southwest", "se", "southeast"};
north_names = {"n", "north", "nw", "northwest", "ne", "northeast"};
east_names = {"e", "east", "ne", "northeast", "se", "southeast"};
west_names = {"w", "west", "nw", "northwest", "sw", "southwest"};
ship_names = {"f", "foreward", "fore", "forward", "aft", "a", "port", "p", "starboard", "sb"};
up_names = {"u", "up"};
down_names = {"d", "down"};
long_exits = this.long_exits;
while (which <= length(rooms))
  check = rooms[which];
  dist = dists[which];
  which = which + 1;
  "for exit in (check.exits)";
  for exit in (check:objects_for_match())
    $command_utils:suspend_if_needed(0);
    if (typeof(dest = `exit.dest ! E_PROPNF') == ERR || !$object_utils:isa(exit, $exit))
      continue exit;
    endif
    if (!(dest in rooms) && (all_obvious || exit:obvious(player)))
      t = dist;
      names = setadd(exit.aliases, exit.name);
      len = exit in long_exits ? 10 | 3;
      if ($object_utils:isa(exit, $door))
        len = 1;
      endif
      if (shippy = su:intersection(names, ship_names))
        names = `{exit.source:island():relative_cardinal(shippy[0])} ! ANY => names';
        len = 1;
      endif
      if (su:intersection(names, south_names))
        t[2] = t[2] - len;
      elseif (su:intersection(names, north_names))
        t[2] = t[2] + len;
      endif
      if (su:intersection(names, east_names))
        t[1] = t[1] + len;
      elseif (su:intersection(names, west_names))
        t[1] = t[1] - len;
      endif
      if (su:intersection(names, up_names))
        t[3] = t[3] + len;
      elseif (su:intersection(names, down_names))
        t[3] = t[3] - len;
      endif
      if ((i = dest in destinations) && distances[i] == unreachable)
        distances[i] = t;
        found = found + 1;
        if (found == length(distances))
          return distances;
        endif
      endif
      rooms = {@rooms, dest};
      dists = {@dists, t};
    endif
  endfor
endwhile
return distances;

