"Find all-pairs shortest paths via Floyd-Warshall";
"Returns the NxN matrix of shortest path lenghts.";
{rooms} = args;
n = length(rooms);
far = $list_utils:make(n, $maxint / 2);
nxn = $list_utils:make(n, far);
":walking_cost is very walking-centric, so this just uses '1' as the length of every exit.";
"if you want another cost, initialize it in the upper loop";
for i in [1..n]
  "using only :obvious_exits() means some rooms which are _restrict_reachable for the player would be unreachable as computed here, paradoxically leading them to be \"most central\" because you can't get *in* to them via only *obvious* exits so they would have the fewest max-cost paths";
  for exit in (rooms[i]:exits())
    j = exit.dest in rooms;
    if (j)
      nxn[i][j] = 1;
    endif
  endfor
endfor
for k in [1..n]
  krow = nxn[k];
  for i in [1..n]
    irow = nxn[i];
    for j in [1..n]
      thru_k = irow[k] + krow[j];
      if (thru_k < irow[j])
        irow[j] = thru_k;
      endif
    endfor
    nxn[i] = irow;
    $command_utils:suspend_if_needed(0);
  endfor
endfor
return nxn;

"pick the most central (by bfs walking distance among all selected rooms) rooms in the candidates";
"";
{rooms, player, location} = args;
"First find the reachable rooms from the current location";
"dists = this:_find_distance_bfs(location, rooms, 0);";
nxn = this:floyd_warshall(rooms);
n = length(rooms);
costs = {};
for i in [1..n]
  $command_utils:suspend_if_needed(0);
  cost = 0.0;
  row = nxn[i];
  for j in [1..n]
    cost = cost + tofloat(row[j]);
  endfor
  $command_utils:suspend_if_needed(0);
  costs = {@costs, cost};
endfor
return this:pick_all_min(rooms, costs);

"@register <object> on $local";
"";
"Add a property to $local with the name as you specify on the command line and the value the matching object.  The name should be a legal MOO identifier so that no quoting is necessary when refering to it from verbs.  You may have to give the object an additional suitable alias before registering it.";
